import{c as s,Q as e,j as i,m as t}from"./chunks/framework.W-g_WCNV.js";const k=JSON.parse('{"title":"Access policies","description":"Restrict which users can access specific apps using policies.","frontmatter":{"title":"Access policies","description":"Restrict which users can access specific apps using policies."},"headers":[],"relativePath":"admin/policies.md","filePath":"admin/policies.md"}'),n={name:"admin/policies.md"};function p(l,a,r,h,o,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<p>A policy is a named list of users. Once created, you can attach a policy to an OIDC client or a ForwardAuth route. Only users in the policy can complete authentication for that app - everyone else is denied access.</p><h2 id="creating-a-policy" tabindex="-1">Creating a policy <a class="header-anchor" href="#creating-a-policy" aria-label="Permalink to &quot;Creating a policy&quot;">​</a></h2><p>Go to <code>/admin/policies</code> and click <strong>New policy</strong>.</p><p>Give it a short, descriptive name. The name is used in the <code>?policy=</code> URL parameter, so stick to lowercase letters, digits, and dashes (for example <code>internal-team</code> or <code>beta-users</code>). The description is optional - it is shown on the policies list page.</p><h2 id="adding-users-to-a-policy" tabindex="-1">Adding users to a policy <a class="header-anchor" href="#adding-users-to-a-policy" aria-label="Permalink to &quot;Adding users to a policy&quot;">​</a></h2><p>Open the policy detail page (<code>/admin/policies/&lt;id&gt;</code>). The <strong>Add user</strong> section at the bottom shows a dropdown of all users not already in the policy. Select a user and click <strong>Add</strong>.</p><p>To remove a user, click <strong>Remove</strong> next to their name in the members table.</p><h2 id="attaching-a-policy-to-an-oidc-client" tabindex="-1">Attaching a policy to an OIDC client <a class="header-anchor" href="#attaching-a-policy-to-an-oidc-client" aria-label="Permalink to &quot;Attaching a policy to an OIDC client&quot;">​</a></h2><p>Open <code>/admin/clients</code> and create or edit a client. The <strong>Required policy</strong> field shows a dropdown of all existing policies. Select one and save. Users who are not in that policy will see an &quot;Access denied&quot; screen after authenticating instead of being redirected back to the app.</p><p>Leave the field set to &quot;No restriction&quot; to allow all authenticated users.</p><h2 id="using-the-policy-query-parameter-with-forwardauth" tabindex="-1">Using the policy query parameter with ForwardAuth <a class="header-anchor" href="#using-the-policy-query-parameter-with-forwardauth" aria-label="Permalink to &quot;Using the policy query parameter with ForwardAuth&quot;">​</a></h2><p>When using the Traefik ForwardAuth middleware, append <code>?policy=&lt;name&gt;</code> to the verify URL. GateKeeper returns HTTP 403 if the authenticated user is not in the named policy.</p><h3 id="traefik-example" tabindex="-1">Traefik example <a class="header-anchor" href="#traefik-example" aria-label="Permalink to &quot;Traefik example&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  middlewares</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gk-internal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      forwardAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com/auth/verify?policy=internal-team&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        authResponseHeaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-Email</span></span></code></pre></div><h3 id="nginx-auth-request-example" tabindex="-1">Nginx auth_request example <a class="header-anchor" href="#nginx-auth-request-example" aria-label="Permalink to &quot;Nginx auth_request example&quot;">​</a></h3><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /auth </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    internal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://auth.example.com/auth/verify?policy=internal-team;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass_request_body </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content-Length </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Original-URI $request_uri;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="caddy-forward-auth-example" tabindex="-1">Caddy forward_auth example <a class="header-anchor" href="#caddy-forward-auth-example" aria-label="Permalink to &quot;Caddy forward_auth example&quot;">​</a></h3><div class="language-caddyfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddyfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forward_auth auth.example.com {</span></span>
<span class="line"><span>    uri /auth/verify?policy=internal-team</span></span>
<span class="line"><span>    copy_headers X-Auth-User X-Auth-Email</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If no <code>?policy=</code> parameter is given, any authenticated user is allowed through.</p><h2 id="credential-injection" tabindex="-1">Credential injection <a class="header-anchor" href="#credential-injection" aria-label="Permalink to &quot;Credential injection&quot;">​</a></h2><p>Some apps do not support SSO or header-based authentication. They require a username and password every time. Credential injection lets GateKeeper supply those credentials automatically after a successful ForwardAuth check, so users never see the app&#39;s own login form.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>Store the app&#39;s username and password on the policy detail page under <strong>Credential injection</strong>. The password is encrypted with AES-256-GCM using <code>SECRET_KEY</code> before it is written to the database.</li><li>When <code>/auth/verify?policy=&lt;name&gt;</code> returns <code>200</code>, GateKeeper sets an <code>Authorization: Basic &lt;base64&gt;</code> header on the response.</li><li>Your reverse proxy is configured to copy that header to the upstream request.</li><li>The app receives a pre-authenticated request and logs the user in without prompting.</li></ol><h3 id="setting-credentials" tabindex="-1">Setting credentials <a class="header-anchor" href="#setting-credentials" aria-label="Permalink to &quot;Setting credentials&quot;">​</a></h3><p>Open the policy detail page and scroll to the <strong>Credential injection</strong> card. Enter the username and password for the downstream app and click <strong>Save</strong>. Leave the password blank when updating to keep the current password unchanged.</p><p>To remove credentials, click <strong>Clear</strong>.</p><h3 id="traefik-configuration" tabindex="-1">Traefik configuration <a class="header-anchor" href="#traefik-configuration" aria-label="Permalink to &quot;Traefik configuration&quot;">​</a></h3><p>Add <code>Authorization</code> to <code>authResponseHeaders</code> so Traefik forwards the injected header to the app:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  middlewares</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sonarr-auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      forwardAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com/auth/verify?policy=sonarr&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        authResponseHeaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-Email</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-Auth-Groups</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Authorization</span></span></code></pre></div><h3 id="app-setup" tabindex="-1">App setup <a class="header-anchor" href="#app-setup" aria-label="Permalink to &quot;App setup&quot;">​</a></h3><p>Configure the downstream app to accept Basic authentication. In Sonarr, Radarr, and similar apps this is found under <strong>Settings - General - Authentication</strong>. Set the method to <strong>Basic</strong> and enter the same username and password you saved in GateKeeper. The app will see the injected <code>Authorization</code> header and skip its own login prompt.</p><h3 id="nginx-and-caddy" tabindex="-1">Nginx and Caddy <a class="header-anchor" href="#nginx-and-caddy" aria-label="Permalink to &quot;Nginx and Caddy&quot;">​</a></h3><p>Nginx&#39;s <code>auth_request</code> module does not copy response headers to the upstream automatically. Use <code>auth_request_set</code> to capture the header and then <code>proxy_set_header</code> to forward it:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auth_request_set </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$auth_cred $upstream_http_authorization;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Authorization $auth_cred;</span></span></code></pre></div><p>Caddy&#39;s <code>forward_auth</code> directive uses <code>copy_headers</code>:</p><div class="language-caddyfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddyfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forward_auth auth.example.com {</span></span>
<span class="line"><span>    uri /auth/verify?policy=sonarr</span></span>
<span class="line"><span>    copy_headers X-Auth-User X-Auth-Email X-Auth-Groups Authorization</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,36)])])}const u=s(n,[["render",p]]);export{k as __pageData,u as default};
